-- Per-word English -> Arabic translations, powering the current-word card
-- shown while typing (normal + stories modes). Nullable by design, same
-- pattern as sentences.audio_url and lessons.illustration_url: NULL means
-- "no word-level translations authored for this sentence yet" (e.g.
-- conversation mode), and the learner UI hides the card gracefully in that
-- case rather than breaking.
alter table sentences
  add column if not exists word_translations jsonb;

-- Backfill for the 144 already-seeded normal + stories sentences (see
-- src/data/lessons/normal.ts and stories.ts, the source of truth this was
-- generated from). Hand-authored word-by-word, not a mechanical split of
-- the whole-sentence English/Arabic text — English and Arabic word order
-- and count don't line up, so a positional split would often be wrong.
-- Conversation mode is intentionally not backfilled; it has no word card.
update sentences set word_translations = '[{"en":"Hi,","ar":"مرحبًا"},{"en":"my","ar":"لي"},{"en":"name","ar":"اسم"},{"en":"is","ar":"يكون"},{"en":"Sarah","ar":"سارة"}]'::jsonb where id = 'normal-1-s1';
